import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        T = int(next(iterator))
    except StopIteration:
        return

    results = []
    for _ in range(T):
        try:
            N = int(next(iterator))
            strings = []
            for _ in range(N):
                strings.append(next(iterator))
        except StopIteration:
            break

        result = []
        for i in range(N):
            char_at_i = strings[i][i]
            if char_at_i == '0':
                result.append('1')
            else:
                result.append('0')

        results.append("".join(result))

    for res in results:
        print(res)

if __name__ == "__main__":
    solve()
